query journalpost($queryJournalpostId: String!) {
  journalpost(journalpostId: $queryJournalpostId) {
    journalposttype
    journalstatus
    tema
    bruker {
      id
      type
    }
    avsenderMottaker {
      id
      navn
      land
      erLikBruker
    }
    dokumenter {
      dokumentInfoId
      tittel
      brevkode
      dokumentstatus
      dokumentvarianter {
        saksbehandlerHarTilgang
        variantformat
      }
    }
  }
}
